// Üretilen dosya: tool/ozgun/uret.py. Doğa · Koruma biyolojisi, nesli tükenen türler ve millî parklar (kolay).
const ozNature13Kolay = <(String, String, List<String>, String)>[
  ('Güney Afrika\'da yaşayan, yalnızca ön yarısında çizgi taşıyan zebra alt türünün bilinen son bireyi 1883\'te Amsterdam\'daki bir hayvanat bahçesinde öldü. Bu hayvan hangisidir?', 'Kuagga', ['Bontebok', 'Tarpan', 'Okapi'], 'Kuagga, ovalar zebrasının güneydeki bir alt türüydü ve yerleşimcilerce avlanarak yok edildi. Bontebok ve okapi başka hayvanlardır, tarpan ise yabani attır.'),
  ('Bilinen son tilasin (Tazmanya kaplanı) 1936\'da hangi kentin hayvanat bahçesinde öldü?', 'Hobart', ['Sidney', 'Melbourne', 'Perth'], 'Son esir tilasin Tazmanya\'nın başkenti Hobart\'taki Beaumaris Hayvanat Bahçesi\'nde öldü. Türe yasal koruma ise ancak ölümünden kısa süre önce getirilmişti.'),
  ('Yeni Zelanda\'da insanlar gelmeden önce otlayan, kanatları tamamen körelmiş ve 15. yüzyıl dolaylarında Polinezyalı yerleşimcilerce tüketilen dev kuş grubu hangisidir?', 'Moa', ['Kivi', 'Emu', 'Kazuar'], 'Moalar, adada kara memelisi olmadığı için büyük otçul işlevini üstlenmişti. Avlanma ve yaşam alanı yakılması nedeniyle birkaç yüzyıl içinde yok oldu.'),
  ('Büyük Set Resifi\'ndeki Bramble Cay\'de yaşayan bir kemirgen (Bramble Cay melomysi) koruma tarihinde neden önemli sayılır?', 'İklim değişikliği nedeniyle tükendiği kabul edilen ilk memeli olması', ['Kıta ülkelerinde tükenen son memeli olması ve avlanma nedeniyle yok olması', 'Yapay üremeyle kurtarılan ilk kemirgen olması', 'İnsanlarla hiç temas etmemiş son memeli olması'], 'Adanın deniz seviyesi yükselişi ve fırtına sellerinden etkilenmesi türün yaşam alanını yok etti. Tür 2019\'da resmen tükenmiş ilan edildi.'),
  ('Batı Afrika kara gergedanının 2011\'de IUCN tarafından tükenmiş ilan edilmesinin başlıca nedeni hangisidir?', 'Boynuzları için yapılan kaçak avcılık', ['Otlak alanlarının tuzlanması ve kuruması sonucu açlık', 'Hayvanat bahçesine yoğun alım', 'Yerel hastalık salgınları'], 'Gergedan boynuzu kara borsada yüksek değerlidir; Orta ve Batı Afrika\'da koruma önlemlerinin zayıf kalması alt türün sonunu getirdi.'),
  ('Bir türün birkaç bireyi sağ olduğu hâlde bu bireyler artık üreyemeyecek ya da ekosistemde işlevini sürdüremeyecek kadar azalmışsa türün durumuna ne ad verilir?', 'İşlevsel (fonksiyonel) yok oluş', ['Yerel yok oluş', 'Kitlesel yok oluş', 'Yapay seçilim'], 'İşlevsel yok oluşta tür tamamen yok olmamıştır, ancak popülasyon ekosistemdeki rolünü ve üreme yeteneğini yitirmiştir. Bu bir tükenme öncesi aşamadır.'),
  ('Gri kurt İngiltere\'de yüzyıllar önce tükenmiş, oysa Kanada ve Rusya\'da hâlâ yaşamaktadır. Kurdun İngiltere\'deki durumunu en iyi anlatan kavram hangisidir?', 'Yerel yok oluş', ['Küresel yok oluş', 'Endemizm', 'Gen akışı'], 'Türün belirli bir bölgeden silinmesi, başka yerlerde yaşıyor olması nedeniyle yerel (bölgesel) yok oluş olarak adlandırılır. Küresel yok oluşta tür dünyadan tamamen kaybolur.'),
  ('Madagaskar\'da yaşamış, bilinen en büyük kuş yumurtalarını bırakan ve yaklaşık bin yıl önce insanlar adaya yayılırken yok olan uçamayan dev kuş hangisidir?', 'Fil kuşu (Aepyornis)', ['Dodo (Mauritius uçamayan güvercini)', 'Moa', 'Büyük auk'], 'Fil kuşunun yumurtası dev boyutlu olup fosil olarak günümüze ulaşmıştır. Tür, insan etkisiyle yaklaşık bin yıl önce yok olmuştur.'),
  ('Galápagos\'taki Pinta Adası kaplumbağasının bilinen son bireyi Lonesome George 2012\'de öldü. George\'un koruma tarihindeki simge değeri neye dayanır?', 'Kendi alt türünün tek bilinen temsilcisi olması', ['Hayvanat bahçesinde yüz yıldan uzun yaşaması', 'İlk radyo vericili kaplumbağa olması', 'Darwin tarafından ele alınan ilk kaplumbağa olması'], 'George\'un ölümüyle Pinta Adası\'na özgü alt türün tükendiği kabul edildi. Avlanma ve adaya bırakılan keçilerin bitkileri yemesi düşüşün başlıca nedenleriydi.'),
  ('Evcil sığırın atası olan ve son dişisi 1627\'de Polonya\'daki Jaktorów ormanında ölen yabani sığırın adı nedir?', 'Aurochs', ['Avrupa bizonu (Bison bonasus) ve yaban öküzü', 'Yak', 'Su sığırı'], 'Aurochs (Bos primigenius) avlanma ve otlak kaybıyla azaldı. Avrupa bizonu ise farklı bir türdür ve hâlâ yaşamaktadır.'),
  ('Belirli bir süre boyunca (örneğin 100 yıl) belirli bir olasılıkla (örneğin %95) sürmesi için gereken en küçük popülasyon büyüklüğüne ne ad verilir?', 'Asgari yaşayabilir popülasyon (MVP)', ['Taşıma kapasitesi (bir alanın taşıyabileceği en çok birey sayısı)', 'Kurucu popülasyon', 'Biyotik potansiyel'], 'MVP, bir türün belirli bir yok oluş riskinin altında kalabilmesi için gereken en küçük sayıdır. Hesabı yaşam öyküsü ve çevreye göre türden türe değişir.'),
  ('Küçülen bir popülasyonda genetik sürüklenme ve soy içi üremenin üreme başarısını azaltması, bunun da popülasyonu daha da küçültmesi döngüsüne ne denir?', 'Yok oluş girdabı', ['Besin zinciri', 'Ekolojik süksesyon', 'Yakınsama'], 'Gilpin ve Soulé\'nin tanımladığı yok oluş girdabında genetik, demografik ve çevresel etkenler birbirini güçlendirerek popülasyonu tükenişe sürükler.'),
  ('Küçük ve kapalı popülasyonlarda soy içi üreme depresyonunun temel genetik nedeni nedir?', 'Zararlı çekinik alellerin homozigot hâle gelmesi', ['Dominant alellerin zamanla tamamen kaybolması ve azalması', 'Mutasyon hızının birdenbire artması', 'Kromozom sayısının ikiye katlanması'], 'Akraba bireylerin eşleşmesi, atalardan gelen zararlı çekinik alellerin çift kopyalı (homozigot) olarak ortaya çıkma olasılığını artırır. Bunun sonucu doğurganlık ve yaşama gücü düşer.'),
  ('Bir yıl şiddetli kuraklık yüzünden bir popülasyonun yavrularının çoğunun ölmesi, hangi tür rastlantısal etkiye örnektir?', 'Çevresel stokastisite', ['Demografik stokastisite', 'Genetik sürüklenme', 'Kurucu etkisi'], 'Yağış, sıcaklık ya da besin gibi dış koşullardaki yıldan yıla değişim tüm popülasyonu aynı anda etkiler; bu çevresel stokastisitedir. Büyük popülasyonlar da bundan etkilenebilir.'),
  ('Popülasyon canlılık analizi (PVA) en çok hangi amaçla kullanılır?', 'Bir popülasyonun belirli sürede yok olma olasılığını modellemek için', ['Bir türün evrimsel akrabalarını ve atasını belirleyip soy ağacı çizmek için', 'Bir bölgedeki tüm türlerin listesini çıkarmak için', 'Bir alanın turistik değerini hesaplamak için'], 'PVA, doğum ve ölüm oranları, genetik ve çevresel belirsizlik gibi verilerle simülasyon yapar. Böylece yönetim seçeneklerinin yok oluş riskine etkisi karşılaştırılır.'),
  ('IUCN Kırmızı Liste\'de şu an tehdit altında olmayan ama yakın gelecekte tehdit altına girme olasılığı bulunan ya da sınıra yakın türler hangi kategoridedir?', 'Yakın tehdit altında (NT)', ['Yetersiz veri (DD), kategori verilemeyen türler', 'Değerlendirilmedi (NE)', 'Doğada tükenmiş (EW)'], 'NT, tehdit altı (VU, EN, CR) eşiklerine yaklaşan ya da bazı koruma önlemlerine bağlı türleri kapsar. Düşük riskli (LC) türlerden bir basamak yukarıdadır.'),
  ('IUCN Kırmızı Liste\'de "Değerlendirilmedi" (NE) kategorisi hangi durumu ifade eder?', 'Türün henüz hiçbir kritere göre değerlendirilmemiş olmasını', ['Türün değerlendirmeye yetecek veriye sahip olmadığının saptanmasını', 'Türün tehdit altında olmadığının kesinleşmesini', 'Türün esarette üretiliyor olmasını'], 'NE, türün henüz kriterlere göre sınanmadığı anlamına gelir. Yetersiz veri (DD) ise türün değerlendirildiği ama veri yetersizliği nedeniyle kategori verilemediği durumdur.'),
  ('CITES sözleşmesinde, ticareti ticari amaçla büyük ölçüde yasaklanan, nesli en çok tehlikedeki türlerin yer aldığı liste hangisidir?', 'Ek I', ['Ek II', 'Ek III', 'Ek IV'], 'CITES Ek I, yok olma tehlikesindeki türleri kapsar ve bu türlerin uluslararası ticareti yalnızca istisnai koşullarda mümkündür. Ek II ise ticareti denetim altına alınan türleri içerir.'),
  ('CITES\'in Ek II listesi hangi türleri kapsar?', 'Şu an tehlikede olmasa da ticareti denetlenmezse tehlikeye girebilecek türleri', ['Yalnızca tükenmiş türleri', 'Yalnız evcilleştirilmiş türleri', 'Yalnızca bitki türlerini'], 'Ek II\'deki türlerin ticareti ihracat izni gibi denetimlere bağlıdır. Böylece ticaret türün hayatta kalmasını tehlikeye atmayacak düzeyde tutulur.'),
  ('Afrika filinin 1989\'da CITES Ek I\'e alınmasının doğrudan sonucu ne olmuştur?', 'Fildişinin uluslararası ticaretinin yasaklanması', ['Filleri avlamanın dünyada tamamen yasaklanması', 'Filleri hayvanat bahçelerine taşımanın serbest kalması', 'Bütün Afrika\'da fil nüfusunun sayılması'], 'Karar fildişinin sınır ötesi ticaretini yasakladı ve kaçak avcılık baskısını azaltmayı amaçladı. Filleri ulusal sınırlar içinde yönetmek ise ülkelerin kendi yetkisinde kaldı.'),
  ('1992\'de Rio\'da imzaya açılan Biyolojik Çeşitlilik Sözleşmesi\'nin üç ana hedefinden biri hangisidir?', 'Genetik kaynaklardan sağlanan yararın adil paylaşımı', ['Bütün hayvanat bahçelerini kapatmak', 'Küresel nüfusu tüm ülkelerde sabitlemek ve sınırlandırmak', 'Atmosferdeki karbondioksiti ölçmek'], 'Sözleşmenin üç hedefi biyolojik çeşitliliğin korunması, bileşenlerinin sürdürülebilir kullanımı ve genetik kaynakların kullanımından doğan yararın adil paylaşımıdır.'),
  ('Nagoya Protokolü hangi konuyu düzenler?', 'Genetik kaynaklara erişim ve yararların adil paylaşımı', ['Tehlikeli atık ticaretinin ve taşınmasının sınırlandırılması ve denetimi', 'Balina avcılığının kısıtlanması', 'Göçmen kuşların halkalanması'], 'Protokol, bir ülkenin biyolojik kaynaklarını (örneğin ilaç yapımında kullanılan bitkileri) kullanan şirketlerin, kaynağın sahibi ülke ve topluluklarla yararı paylaşmasını öngörür.'),
  ('UNESCO Dünya Miras Sözleşmesi\'nde hem doğal hem kültürel ölçütleri sağlayan alanlara ne ad verilir?', 'Karma miras alanı', ['Çift ölçütlü miras alanı', 'Tabiat anıtı', 'Biyosfer rezervi'], 'Karma alanlar hem olağanüstü doğal özellikler hem de kültürel değer taşır. Sözleşme 1972\'de kabul edilmiştir.'),
  ('Bir UNESCO biyosfer rezervinde yalnızca korunması ve izlenmesi amaçlanan, insan etkinliğinin sıkı biçimde sınırlandırıldığı bölge hangisidir?', 'Çekirdek bölge', ['Geçiş bölgesi', 'Tampon kuşak', 'Yerleşim kuşağı'], 'Biyosfer rezervleri çekirdek, tampon ve geçiş olmak üzere üç bölgeden oluşur. Çekirdek bölgede koruma önceliklidir, geçiş bölgesinde ise yerleşim ve tarım sürdürülür.'),
  ('Artvin\'in Borçka ilçesindeki Camili bölgesi hangi uluslararası statüye sahiptir?', 'UNESCO biyosfer rezervi', ['Ramsar alanı', 'Dünya mirası kültürel alan', 'UNESCO yaratıcı şehir'], 'Camili, 2005\'te Türkiye\'nin ilk biyosfer rezervi olarak tanındı. Yoğun yağış alan Karadeniz\'in yaşlı orman ve yayla kültürü bir arada korunur.'),
  ('ABD\'de 1973 tarihli Nesli Tehlike Altındaki Türler Yasası\'nın en belirgin yaptırımı nedir?', 'Listelenen türlere zarar vermeyi ve yaşam alanlarını bozmayı yasaklaması', ['Hayvanat bahçelerini kapatması', 'Bütün avcılığı yasaklaması', 'Sınırdaki tüm bitki ithalatını durdurması'], 'Yasa, listeye alınan türlerin öldürülmesini ya da zarar görmesini yasaklar ve kritik yaşam alanlarının korunmasını öngörür. Kel kartal gibi türlerin toparlanmasında rol oynamıştır.'),
  ('1932\'de Kanada ve ABD arasında kurulan Waterton-Glacier Uluslararası Barış Parkı hangi türden bir korunan alan örneğidir?', 'İki ülkeye yayılan sınır ötesi koruma alanı', ['Yalnızca denizlerdeki balıkçılık ve koruma alanı', 'Askerî bölge', 'Botanik bahçesi'], 'Barış parkları, ülke sınırını aşan ekosistemleri ortak yönetmek için kurulur. Hayvanlar sınır tanımadığından bu yaklaşım koruma açısından değerlidir.'),
  ('Botsvana ile Güney Afrika\'nın sınırında kurulan Kgalagadi Sınır Ötesi Parkı\'nın koruma açısından temel yararı nedir?', 'Hayvanların sınırlar arasında göç edebilmesi', ['Gelirlerin yalnız tek ülkeye ve özel şirketlere kalması', 'Yerleşimcilerin serbestçe avlanması', 'Çölde tarım yapılması'], 'Sınır ötesi parklarda çitler kaldırılarak büyük memelilerin mevsimlik hareketlerine alan açılır. Ayrıca iki ülke koruma çalışmalarını birlikte yürütür.'),
  ('Bir bataklığın kurutulup tarım alanına çevrilmesi, aşağıdakilerden hangisine örnektir?', 'Habitat kaybı', ['Habitat parçalanması', 'Habitat bozulması', 'Habitat restorasyonu'], 'Habitatın tamamen başka bir kullanıma dönüşmesi habitat kaybıdır. Parçalanmada alan bölünür, bozulmada ise kalite düşer ama alan kalır.'),
  ('E. O. Wilson\'a atfedilen HIPPO kısaltmasında harflerden biri biyoçeşitlilik kaybının hangi nedenini ifade eder?', 'Aşırı avlanma ve toplama', ['Hidroelektrik santrallerin nehirlere zarar vermesi', 'Hava durumu', 'Hızlı ormancılık'], 'HIPPO; yaşam alanı kaybı (Habitat loss), istilacı türler (Invasive species), kirlilik (Pollution), insan nüfusu (human Population) ve aşırı avlanma ya da toplamadır (Overharvesting).'),
  ('Yeni bir koruma alanı seçilirken mevcut korunan alanlarda temsil edilmeyen türleri kapsayan bölgenin tercih edilmesi hangi ilkeye dayanır?', 'Tamamlayıcılık', ['Tekrarlama ve çoğaltma ilkesi', 'Ekolojik tuzak', 'Zonasyon'], 'Tamamlayıcılık ilkesinde her yeni alan, ağın eksik bıraktığı biyoçeşitlilik öğelerini ekleyecek biçimde seçilir. Böylece sınırlı bütçe ile temsil artırılır.'),
  ('Koruma boşluk analizi (gap analysis) ne işe yarar?', 'Biyoçeşitliliğin hangi öğelerinin korunan alanlarla yeterince temsil edilmediğini belirler', ['Türlerin yaşını tahmin eder', 'Hayvan sayısını genetik olarak hesaplar', 'Millî park ziyaretçi sayısını artırır'], 'Boşluk analizi türlerin dağılım haritası ile korunan alanlar haritasını çakıştırır. Korunmayan türler ve yaşam alanları öncelikli hâle gelir.'),
  ('Bir ekosistemin sağlığı hakkında bilgi veren, çevre değişikliklerine duyarlı olduğu için izlenen türe ne ad verilir?', 'Gösterge tür', ['Şemsiye tür', 'Bayrak tür', 'Anahtar tür'], 'Gösterge türlerin sayısındaki ve sağlığındaki değişim çevre kirliliği ya da yaşam alanı bozulması gibi sorunları erkenden haber verebilir.'),
  ('Bozulmuş bir sulak alanda yalnızca kaçak otlatmayı ve kurutma kanallarını kaldırarak doğal yenilenmeyi beklemek hangi restorasyon yaklaşımıdır?', 'Pasif restorasyon', ['Aktif restorasyon', 'Ex situ koruma', 'Yeniden yabanıllaştırma'], 'Pasif restorasyonda tehdit ortadan kaldırılır ve doğa kendi kendine toparlanır. Aktif restorasyonda ise fidan dikme gibi doğrudan müdahaleler yapılır.'),
  ('Bir popülasyonda yıllık doğal artış 50 birey iken avcılar 80 birey avlıyor. Popülasyonun sürdürülebilirliği için ne söylenebilir?', 'Av baskısı artışı aştığı için popülasyon azalır', ['Popülasyon dengede kalır, çünkü ölümler ve doğumlar eşitlenir', 'Popülasyon hızla büyür', 'Av popülasyonu etkilemez'], 'Av, doğal artıştan 30 birey fazladır; bu açık her yıl popülasyonu küçültür. Sürdürülebilir kullanımda av miktarı artışı aşmamalıdır.'),
  ('1990\'larda Hint alt kıtasında üç akbaba türünün sayısı %95\'in üzerinde azaldı. Başlıca neden hangisidir?', 'Sığır leşlerindeki veteriner ilacı diklofenak', ['Kuş gribi salgını ve kırsal bölgelerdeki zehirli yem kullanımı', 'Kış mevsiminin uzaması', 'Leşlerin aşırı azalması'], 'Diklofenak ile tedavi edilen hayvanların leşini yiyen akbabalarda böbrek yetmezliği gelişti. İlacın hayvan hekimliğinde yasaklanmasıyla toparlanma başladı.'),
  ('Hindistan\'ın Assam eyaletindeki Kaziranga Millî Parkı hangi hayvanın dünyadaki en büyük popülasyonlarından birini barındırmasıyla bilinir?', 'Hint (tek boynuzlu) gergedanı', ['Asya aslanı', 'Sumatra gergedanı', 'Kızıl panda'], 'Brahmaputra Nehri\'nin taşkın ovasındaki Kaziranga, tek boynuzlu gergedanın korunmasında en başarılı alanlardan biridir.'),
  ('Hindistan\'da 1973\'te başlatılan Kaplan Projesi\'nin temel yaklaşımı nedir?', 'Çekirdek alanlarda insan yerleşimini sınırlayan özel kaplan koruma alanları ağı kurmak', ['Bütün kaplanları hayvanat bahçelerine toplamak', 'Kaplan avcılığını belirli kotayla serbest bırakmak', 'Kaplanların yeni ülkelere taşınması'], 'Proje, çekirdek bölgede yerleşimi sınırlayıp çevresinde tampon alan oluşturan koruma alanları kurdu. Yöntem sonradan başka ülkelerde de örnek alındı.'),
  ('Nepal\'in 1973\'te kurulan ilk millî parkı olan ve hem Bengal kaplanını hem tek boynuzlu gergedanı koruyan alan hangisidir?', 'Chitwan Millî Parkı', ['Sagarmatha Millî Parkı', 'Langtang Millî Parkı', 'Bardia Millî Parkı'], 'Nepal\'in güneyindeki Terai bölgesinde yer alan Chitwan, geniş çayır ve sal ormanlarıyla bu iki türün önemli sığınağıdır. Sagarmatha ise Himalayaların yüksek kesiminde yer alır.'),
  ('Uganda\'daki Bwindi Geçilmez Ormanı\'nda gorilleri izlemeye dönük, sınırlı sayıda ve izinli turizm, koruma açısından hangi katkıyı sağlar?', 'Yerel halka gelir sağlayıp yaban hayatını korumayı ekonomik açıdan değerli kılar', ['Gorilleri insanlarla tanıştırarak evcilleştirir', 'Ormanı tarım alanına açar', 'Gorillerin sayısını kasıtlı olarak azaltır'], 'Kontrollü turizm gelirleri park yönetimine ve çevre köylere aktarılır. Böylece kaçak avcılık ve orman açma yerine koruma teşvik edilir.'),
  ('Mauritius kerkenezi 1970\'lerin ortasında dört bireye kadar düştü, bugün yüzlerce bireye ulaştı. Bu toparlanmada hangi yaklaşım temel rol oynadı?', 'Yuva koruma, yapay üretim ve yavruların doğaya salımı', ['Hiçbir müdahale yapılmaması ve türün kendi hâline bırakılması', 'Türün tamamen başka adaya taşınması', 'Yırtıcı hayvanların adadan kaçırılması'], 'Program, yuvaları korudu, ek yumurtaları yapay kuluçkayla çıkardı ve doğaya yavru saldı. Yoğun müdahaleyle gelen başarı örneklerinden biridir.'),
  ('California kondoru yavrularının besinin insan elleri yerine kondor biçimli kuklalarla verilmesinin amacı nedir?', 'Yavruların insana damgalanmasını önlemek', ['Yavruların daha hızlı büyümesini sağlamak', 'Yavruların ses çıkarmasını engellemek', 'Bakıcıların yaralanmasını önlemek'], 'Damgalanan (imprinting) yavru, insanı kendi türünden sayabilir ve doğada eş bulamaz. Kukla kullanımı, doğaya salınacak bireylerin tür kimliğini korur.'),
  ('Afrika Birliği\'nin 2007\'de başlattığı ve Sahel boyunca uzanan "Büyük Yeşil Duvar" girişiminin amacı nedir?', 'Çölleşmeyi durdurmak ve bozulmuş arazileri yeniden yeşillendirmek', ['Sahra\'yı hayvan geçişine kapatmak', 'Kuzey Afrika\'ya sınır çiti örmek', 'Okyanus kıyısını tuzlanmadan korumak'], 'Girişim, Sahel kuşağında ağaç dikimi ve toprak ıslahıyla çölleşme, yoksulluk ve iklim etkilerini azaltmayı hedefler. Bütünüyle sürekli bir ağaç şeridi olarak değil, mozaik uygulamalar şeklinde ilerler.'),
  ('Kruger Millî Parkı\'nın temelini oluşturan 1898 tarihli Sabie Koruma Alanı\'nın kurulmasında etkili olan, Transvaal Cumhuriyeti\'nin başkanı kimdir?', 'Paul Kruger', ['Cecil Rhodes', 'Jan Smuts', 'Nelson Mandela'], 'Park adını Transvaal Cumhurbaşkanı Paul Kruger\'den alır; 1926\'da millî park statüsüne kavuşmuştur. Rhodes ve Smuts başka tarihsel kişilerdir.'),
  ('Türkiye\'de korunan alan statülerinden hangisinde yalnızca bilimsel araştırma ve eğitim amaçlı etkinliklere izin verilir ve alan halka kapalıdır?', 'Tabiat koruma alanı', ['Tabiat parkı', 'Yaban hayatı geliştirme sahası', 'Millî park'], 'Tabiat koruma alanları, bilimsel açıdan ender türleri ya da ekosistemleri barındıran alanlardır. Halkın dinlenmesine açık olan statü ise tabiat parkıdır.'),
  ('Bitki örtüsü ve manzara güzelliği taşıyan, halkın dinlenip eğlenmesine uygun olan ve doğal ortamı bozmayacak biçimde düzenlenen korunan alan türü hangisidir?', 'Tabiat parkı', ['Tabiat koruma alanı', 'Özel çevre koruma bölgesi', 'Gen koruma sahası'], 'Tabiat parkları, doğa ile iç içe dinlenmeyi sağlamak üzere ilan edilir. Tabiat koruma alanlarından farklı olarak ziyarete açıktır.'),
  ('Bir doğal sit alanının 1. derece olarak belirlenmesi, alanda hangi sonucu doğurur?', 'Koruma dışındaki yapılaşma ve kullanıma izin verilmemesi', ['Her türlü konutun ve ticari yapının kısıtlama olmadan serbestçe yapılabilmesi', 'Yalnızca ticari tesislerin kurulabilmesi', 'Alanın tarıma açılması zorunluluğu'], '1. derece doğal sit alanları, kesin korunması gereken nitelikli alanlardır; koruma amaçlı kullanımlar dışında yapılaşmaya izin verilmez. Sınırlı yapılaşma izinleri 3. derece sitlerde söz konusudur.'),
  ('Türkiye\'de avlanabilecek hayvan türlerini, avlanma yer ve zamanını her yıl belirleyen kurul hangisidir?', 'Merkez Av Komisyonu', ['Orman Meclisi', 'Tabiat Varlıkları Kurulu', 'Sulak Alanlar Komitesi'], 'Kara Avcılığı Kanunu\'na dayanan Merkez Av Komisyonu, av hayvanlarının listesini ve avlanma kurallarını belirler. Üreme dönemindeki türlerin avlanması bu kurallarla yasaklanır.'),
  ('Av sezonunun belirli aylara sınırlanmasının ve üreme mevsiminde avlanmanın yasaklanmasının temel koruma gerekçesi nedir?', 'Popülasyonun yavru üretip sayısını koruyabilmesine olanak vermek', ['Avcıların ruhsat ücretini artırmak', 'Hayvanların göç yollarını değiştirmek', 'Av etinin raf ömrünü uzatmak'], 'Üreme döneminde avlanma, hem anne bireyleri hem de bağımlı yavruları yok ederek popülasyonu çökertir. Yasak dönem bu kaybı önler.'),
  ('Aşağıdaki sulak alan-il eşleştirmelerinden hangisi doğrudur?', 'Seyfe Gölü – Kırşehir', ['Sultan Sazlığı – Edirne', 'Uluabat Gölü – Adana', 'Akyatan Lagünü – Bursa'], 'Seyfe Gölü Kırşehir\'de, Sultan Sazlığı Kayseri\'de, Uluabat Gölü Bursa\'da, Akyatan Lagünü ise Adana\'dadır. Bu alanlar Türkiye\'deki önemli sulak alanlardandır.'),
  ('Hierapolis-Pamukkale 1988\'de UNESCO Dünya Mirası Listesi\'ne hangi kategoride alınmıştır?', 'Karma (doğal ve kültürel) miras', ['Yalnızca doğal miras', 'Yalnızca somut olmayan kültürel miras', 'Tehlike altındaki miras'], 'Beyaz travertenler ve antik kent birlikte değerlendirilerek alan, hem doğal hem kültürel ölçütlerle karma miras olarak kaydedilmiştir.'),
  ('Çevresel Etki Değerlendirmesi (ÇED) hangi amaçla yapılır?', 'Bir projenin çevreye olası etkilerini, proje uygulanmadan önce belirlemek ve önlem almak', ['Mevcut fabrikaların üretim miktarını artırmak', 'Doğal alanları otomatik olarak yapılaşmaya açmak', 'Hava durumunu tahmin etmek'], 'ÇED raporu, baraj, maden ya da yol gibi projelerin çevreye zararını daha yapım başlamadan inceleyip alternatif ve önlemleri değerlendirmeyi sağlar.'),
  ('Bir kıyı bölgesinde ekolojik açıdan hassas, ulusal ve uluslararası öneme sahip bir alanı kirlenme ve bozulma baskısına karşı koruma amacıyla belirlenen statü hangisidir?', 'Özel çevre koruma bölgesi', ['Ormaniçi dinlenme yeri ve piknik alanı', 'Av turizmi sahası', 'Avlak'], 'Özel çevre koruma bölgeleri, çevre bakımından hassas alanlar için özel kurallar getirir. Yönetimi bu amaçla kurulmuş özel bir kurum yürütür.'),
  ('Siirt\'te yer alan Botan Vadisi Millî Parkı\'ndaki Botan Çayı, hangi akarsuya karışır?', 'Dicle', ['Fırat', 'Kızılırmak', 'Çoruh'], 'Botan Çayı, Dicle Nehri\'nin önemli kollarından biridir. Vadi, derin kanyonları ve yaban hayatıyla 2019\'da millî park ilan edilmiştir.'),
  ('Çanakkale\'deki Gelibolu Yarımadası Tarihî Millî Parkı hangi olayın anısını ve alanını korur?', '1915 Çanakkale Savaşları', ['Büyük Taarruz', 'Sakarya Meydan Muharebesi', 'Dumlupınar Savaşı'], 'Gelibolu Yarımadası\'nda yaşanan çatışmaların izlerini taşıyan alan, tarihî millî park olarak korunur. Büyük Taarruz ise Afyonkarahisar çevresinde gerçekleşmiştir.'),
  ('Hayvanat bahçelerinde "soy kütüğü" (studbook) tutulmasının koruma açısından başlıca amacı nedir?', 'Eşleştirmeleri akrabalığı düşük bireyler arasında planlayıp genetik çeşitliliği korumak', ['Hayvanların yaşını ziyaretçilere göstermek', 'Hayvanları yarışmalarda kayıt altına almak', 'Besleme maliyetini hesaplamak'], 'Soy kütüğü, her bireyin ataları ve çocuklarını kayıt altına alır. Böylece soy içi üreme azaltılır ve yedek popülasyonun genetik sağlığı sürdürülür.'),
  ('Bir tohum bankasında kurutulup dondurularak uzun yıllar saklanabilen tohumlara ne ad verilir?', 'Ortodoks tohumlar', ['Rekalsitran tohumlar', 'Çimlenmiş tohumlar', 'Eşeysiz tohumlar'], 'Ortodoks tohumlar kurumaya ve düşük sıcaklığa dayanabildiği için gen bankalarında uzun süre saklanır. Rekalsitran tohumlar ise kuruyunca canlılığını yitirir.'),
  ('Londra yakınlarındaki Kew Bahçeleri\'ne bağlı Millennium Tohum Bankası\'nın temel amacı nedir?', 'Dünya bitki türlerinin tohumlarını güvenli biçimde saklayıp yok oluş durumunda yedek oluşturmak', ['Tarım ürünlerinin fiyatını belirlemek', 'Çiçek ticaretini düzenlemek', 'Meyve yetiştirme teknikleri satmak'], 'Millennium Tohum Bankası, yabani bitki türlerinin tohumlarını dondurulmuş koşullarda saklar. Programın hedefi, tehdit altındaki bitkileri yedeklemektir.'),
  ('Tehlike altındaki hayvanların hücre ve dokularının sıvı azot içinde dondurularak saklanması, ileride gen çeşitliliği kaybını telafi etmek için hangi tekniğe dayanır?', 'Kriyoprezervasyon', ['Fotosentez', 'Biyolojik mücadele', 'Gen bombardımanı'], 'Kriyoprezervasyon, hücrelerin çok düşük sıcaklıkta canlılık özelliğini koruyarak saklanmasıdır. San Diego\'daki "Donmuş Hayvanat Bahçesi" bu yaklaşımla hücre koleksiyonu tutar.'),
  ('Yeniden yerleştirilecek hayvanların doğaya salınmadan önce yırtıcı kokusu ve sesiyle tehlikeyi tanıma eğitimi alması hangi uygulamadır?', 'Avcıdan kaçınma eğitimi', ['Ex situ üreme', 'Doku kültürü', 'Ortalama akrabalık hesabı'], 'Esarette doğan hayvanlar yırtıcı bilgisini kendiliğinden edinemez. Önceden eğitim, doğaya salındıktan sonra hayatta kalma şansını artırır.'),
  ('Bir akarsuyundan alınan su örneğindeki DNA parçalarından türün orada yaşayıp yaşamadığının belirlenmesine ne ad verilir?', 'Çevresel DNA (eDNA) analizi', ['Kromozom boyama ve sayma analizi', 'Gen terapisi', 'Klonlama'], 'Canlılar dışkı, deri ve mukus yoluyla çevreye DNA bırakır. Su örneğinde türe özgü DNA\'nın saptanması, hayvanı yakalamadan varlığını gösterebilir.'),
  ('Kaçak olarak satılan balık eti ya da hayvansal ürünlerin hangi türden geldiğini belirlemede kullanılan, kısa bir gen bölgesinin dizilenmesine dayalı yönteme ne denir?', 'DNA barkodlama', ['Kariyotip analizi', 'Kan grubu tayini', 'Karbon tarihleme'], 'DNA barkodlama, standart bir gen bölgesinin dizisini referans kütüphanelerle karşılaştırarak türü tanımlar. Parçalanmış ya da işlenmiş ürünlerde bile işe yarayabilir.'),
  ('Bir hayvanın boynuna takılan GPS tasmasının koruma çalışmalarındaki yararı nedir?', 'Alan kullanımını ve göç yolunu ayrıntılı izleyerek koruma planına bilgi sağlaması', ['Hayvanı bölgeden kaçmaya zorlaması', 'Yırtıcıları uzak tutması', 'Hayvanın kendi yiyeceğini bulmasını sağlaması'], 'Tasma, hayvanın konumunu düzenli aralıklarla kaydeder. Bu veriler hangi alanların koridor ya da koruma açısından önemli olduğunu gösterir.'),
  ('İtalya\'nın 1922\'de kurulan ilk millî parkı olan Gran Paradiso, eski bir kraliyet av alanıdır. Bu alan hangi hayvanın Alpler\'de tükenmekten kurtulmasında önemli olmuştur?', 'Alp dağ keçisi', ['Kutup tilkisi ve kar tavşanı', 'Kafkas yaban öküzü', 'Alp kar tavşanı'], '19. yüzyılda Alp dağ keçisinin yalnızca Gran Paradiso çevresindeki az sayıda bireyi kalmıştı. Buradan alınan hayvanlar sonradan Alpler\'in başka yerlerine salındı.'),
  ('Romanya\'daki Tuna Deltası, Avrupa\'da hangi özelliğiyle öne çıkar?', 'En geniş sazlık alanlarına sahip olması', ['En yüksek ve en çok kar tutan dağ zirvelerini barındırması', 'En derin mağara sistemine sahip olması', 'En büyük buzul gölünü içermesi'], 'Tuna Nehri\'nin Karadeniz\'e kavuştuğu bu delta, Avrupa\'daki en büyük sazlık alanını barındırır. Su kuşları için de önemli bir sığınaktır.'),
  ('Güney Fransa\'daki Camargue bölgesi hangi nehrin deltasında yer alır ve flamingoların üreme alanı olarak bilinir?', 'Rhône', ['Seine', 'Loire', 'Garonne'], 'Camargue, Rhône Nehri\'nin Akdeniz\'e ulaştığı yerde oluşan tuzlu lagünler ve bataklıklardan oluşur. Seine, Loire ve Garonne ise Atlas Okyanusu ya da Manş\'a dökülür.'),
  ('İzlanda\'daki Þingvellir Millî Parkı\'nda ortaya çıkan derin yarığın nedeni nedir?', 'Kuzey Amerika ve Avrasya levhalarının birbirinden uzaklaşması', ['İki levhanın birbirine çarpması', 'Buzulların derin vadiler açması', 'Göktaşı çarpması'], 'Orta Atlantik Sırtı\'nın karadaki uzantısında levhalar ayrılırken yarıklar ve çöküntü vadileri oluşur. Þingvellir aynı zamanda tarihî Alþingi meclisinin toplandığı yerdir.'),
  ('Güney Amerika\'da Brezilya, Bolivya ve Paraguay\'a yayılan Pantanal, dünyanın hangi özelliğiyle bilinen sulak alanıdır?', 'En büyük tropik sulak alanlardan biri olması', ['Dünyanın en soğuk ve en kuzey bataklığı olması', 'Yalnızca tuzlu su içermesi', 'Yalnızca dağ zirvesinde yer alması'], 'Pantanal, mevsimsel taşkınlarla suyla kaplanan çok geniş bir tropik sulak alandır. Jaguar ve birçok su kuşu için önemli bir yaşam alanıdır.'),
  ('Venezuela\'daki Canaima Millî Parkı\'nda bulunan Angel Şelalesi\'ni özel kılan nedir?', 'Dünyanın en yüksek kesintisiz şelalesi olması', ['Dünyanın en geniş ve en çok su taşıyan şelalesi olması', 'Dünyanın en soğuk şelalesi olması', 'Dünyanın tek buzul şelalesi olması'], 'Tepui adı verilen masa dağlarından dökülen Angel Şelalesi yaklaşık 979 m yüksekliktedir. Genişliği değil yüksekliği ile bilinir.'),
  ('Namibya\'daki Etosha Millî Parkı\'nın ortasında yer alan ve bölgenin simgesi olan büyük beyaz alan nedir?', 'Kuruyan tuzlu bir göl tabanı', ['Kutupsal buzul', 'Kum tepeleri alanı', 'Volkanik kül alanı'], 'Etosha Pan, çok geniş bir tuz çanağıdır; yağışlı mevsimde sığ gölcüklere dönüşür ve bölgedeki hayvanlar için önemli bir kaynaktır.'),
  ('Zambezi Nehri üzerindeki Victoria Şelalesi\'nin yerel adı "Mosi-oa-Tunya"dır. Bu ad ne anlama gelir?', 'Gürleyen duman', ['Beyaz kraliçenin gözyaşı', 'Altın nehir', 'Sonsuz yağmur'], 'Mosi-oa-Tunya, şelaleden yükselen su buharının uzaktan görülmesi nedeniyle verilen "gürleyen duman" adıdır. Şelale Zambiya ile Zimbabve sınırındadır.'),
  ('Karadağ\'daki Durmitor Millî Parkı\'nda bulunan Tara Kanyonu, Avrupa\'da hangi özelliğiyle bilinir?', 'En derin kanyon olması', ['En uzun mağara olması', 'En yüksek zirve olması', 'En büyük bataklık olması'], 'Tara Nehri\'nin oyduğu kanyon yaklaşık 1300 m derinlikle Avrupa\'nın en derin kanyonudur. Durmitor aynı zamanda UNESCO Dünya Mirası alanıdır.'),
  ('İskoçya\'daki Cairngorms, Birleşik Krallık\'ın hangi özelliğe sahip millî parkıdır?', 'En büyük millî parkı olma', ['İlk kurulan millî parkı olma', 'Tek deniz parkı olma', 'Tek volkanik parkı olma'], '2003\'te kurulan Cairngorms, geniş dağ platosu ve ormanlarıyla Birleşik Krallık\'ın alan bakımından en büyük millî parkıdır. İngiltere\'nin ilk parkı ise 1951\'de kurulan Peak District\'tir.'),
  ('Birleşik Krallık\'ın 1951\'de kurulan ilk millî parkı hangisidir?', 'Peak District', ['Lake District Millî Parkı', 'Snowdonia', 'Cairngorms'], 'Peak District, 1951\'de kurulmuş ve ülkenin ilk millî parkı olmuştur. Lake District ve Snowdonia ise sonradan kurulan parklardır.'),
  ('ABD\'de Grand Canyon Millî Parkı hangi yıl kurulmuştur?', '1919', ['1872 yılında', '1890', '1946'], 'Grand Canyon, 1919\'da millî park ilan edildi. 1872 Yellowstone\'un, 1890 ise Yosemite ve Sequoia\'nın millî park olma yılıdır.'),
  ('IUCN\'nin korunan alan sınıflandırmasında "millî park" hangi kategoriye karşılık gelir?', 'Kategori II', ['Kategori Ia', 'Kategori III', 'Kategori VI'], 'IUCN sisteminde Ia sıkı doğa koruma alanı, Ib vahşi alan, II millî park, III doğal anıt, IV habitat/tür yönetim alanı, V korunan kara-deniz peyzajı, VI sürdürülebilir kullanımlı alandır.'),
  ('1988\'de Yellowstone\'u kasıp kavuran büyük yangınların ardından ekologlar hangi gözlemi yaptı?', 'Birçok bitki ve topluluk yangından sonra kendiliğinden yenilendi', ['Alandaki tüm ekosistem sonsuza dek yok olup bir daha yenilenmedi ve kurudu', 'Yangın sonrası hiçbir bitki çimlenmedi', 'Millî park kalıcı olarak kapatıldı'], 'Yangın bazı ekosistemlerin doğal bir parçasıdır. Murat çamı gibi türlerin kozalakları ısıyla açılır, yangın sonrası yeni fidanlar yetişir.'),
  ('Bir millî parkta günlük ziyaretçi sayısının, alanın ekolojik zarar görmeyeceği düzeyle sınırlandırılması hangi kavrama dayanır?', 'Ziyaretçi taşıma kapasitesi', ['Biyolojik amplifikasyon', 'Genetik sürüklenme', 'Besin zinciri verimi'], 'Taşıma kapasitesi kavramı, alanın aşınma, kirlilik ve rahatsızlık gibi etkilerden zarar görmeden kaldırabileceği ziyaretçi sayısını belirtir.'),
  ('Dünya Yaban Hayatı Günü hangi tarihte kutlanır?', '3 Mart', ['22 Mayıs', '5 Haziran', '4 Ekim'], '3 Mart, CITES\'in imzalandığı günü anmak için BM tarafından yaban hayatı gününe ayrılmıştır. 22 Mayıs biyolojik çeşitlilik, 5 Haziran çevre günüdür.'),
  ('Dünya Biyolojik Çeşitlilik Günü hangi tarihte kutlanır?', '22 Mayıs', ['3 Mart', '21 Mart', '2 Şubat'], 'BM, Biyolojik Çeşitlilik Sözleşmesi\'nin kabul edildiği güne atıfla 22 Mayıs\'ı biyoçeşitlilik günü olarak kutlar.'),
  ('Dünya Sulak Alanlar Günü, Ramsar Sözleşmesi\'nin imzalandığı günün anısına hangi tarihte kutlanır?', '2 Şubat', ['21 Mart', '22 Nisan', '5 Haziran'], 'Ramsar Sözleşmesi 2 Şubat 1971\'de imzalandığı için sulak alanlar günü her yıl 2 Şubat\'ta kutlanır.'),
  ('BM Sürdürülebilir Kalkınma Amaçları arasında karasal ekosistemlerin korunmasını, ormanların sürdürülebilir yönetimini ve biyoçeşitlilik kaybının durdurulmasını hedefleyen amaç hangi sayıyı taşır?', '15', ['14', '13', '12'], 'Amaç 15 "Karasal Yaşam"dır. 14 sualtı yaşamı, 13 iklim eylemi, 12 sorumlu tüketim ve üretimdir.'),
  ('Yalnızca bir korunan alanın ilanı, sahadaki kaçak avcılığı kendiliğinden durdurmaz. "Kâğıt üzerindeki park" deyimi bu durumu nasıl anlatır?', 'Yasal statünün var olup uygulamanın ve kaynağın yetersiz kalması', ['Parkın haritada hiç yer almaması', 'Parkta kâğıt üretilmesi', 'Parkın çok küçük olması'], 'Kâğıt park, sınırları ve kuralları belli olduğu hâlde personel, denetim ve bütçe eksikliği yüzünden fiilen korunmayan alanı anlatır.'),
  ('Namibya\'da çita koruma çalışmalarında sürüleri koruyan Anadolu çoban köpeklerinin kullanılmasının amacı nedir?', 'Çiftçilerin çitalara karşı hayvanlarını koruyup misilleme avını azaltmak', ['Çitaları evcilleştirmek', 'Çitaları avlamak', 'Çitaların yön duygusunu bozmak'], 'Bekçi köpekleri çitaları çiftlikten uzak tutar. Böylece hayvan kaybı azalır ve çiftçiler çitaları öldürmeye daha az yönelir.'),
  ('Elektrik hatlarına çarparak ölen büyük kuşları azaltmak için hatlara yerleştirilen işaretleyiciler nasıl bir önlemdir?', 'Kuşların teli görüp yön değiştirmesini sağlayan azaltıcı önlem', ['Kuşların göç yolunu kapatan engel', 'Kuşları besleyen düzenek', 'Telleri soğutan donanım'], 'Renkli ya da yansıtıcı işaretler teli kuşlara daha görünür kılar. Çarpma ölümlerini azaltmak için yaygın olarak uygulanır.'),
  ('Bir bölgede yağış ve sıcaklık değişse bile görece sabit kalan, türlerin zor dönemde sığınabildiği alanlara ne ad verilir?', 'İklim sığınağı', ['Kenar alan', 'Tampon kuşak', 'Kaynak alan'], 'İklim sığınakları, derin vadi, kuzey yamaç ya da yüksek rakım gibi yerlerde bulunur. Koruma planlamasında bu alanlara öncelik verilmesi önerilir.'),
  ('Kara yüzeyinin yaklaşık %3\'ünü kaplayan turbalıkların iklim açısından önemi nedir?', 'Büyük bir karbon deposu olmaları', ['Çok miktarda oksijen üretip atmosfere vermeleri', 'Rüzgâr hızını artırmaları', 'Çok fazla ısı yaymaları'], 'Turbalıklar, küçük alanlarına karşın çok büyük miktarda karbon depolar. Bozulduklarında ise bu karbon atmosfere salınır.'),
  ('Bir iklim planında bozulmuş bir bataklığın yeniden ıslatılması "doğa temelli çözüm" sayılır. Bu kavram neyi anlatır?', 'Doğal ekosistemlerin korunması veya restorasyonuyla toplumsal sorunlara çözüm üretmeyi', ['Yalnızca teknoloji kullanarak karbon yakalamayı', 'Doğayı tamamen insan kullanımından arındırmayı', 'Yapay ekosistemler kurmayı'], 'Doğa temelli çözümler, ekosistemlerin korunması ve iyileştirilmesiyle iklim, su ve biyoçeşitlilik gibi sorunlara aynı anda yanıt arar.'),
  ('Sertifikalı ürün etiketleriyle ormancılığın ve odun ticaretinin ekolojik ve sosyal ölçütlere göre yapıldığını belgeleyen uluslararası sistem hangisidir?', 'FSC', ['IPBES', 'CITES', 'Ramsar'], 'Orman Yönetim Konseyi (FSC) sertifikası, odunun sorumlu biçimde yönetilen ormanlardan geldiğini gösterir. Böylece tüketiciler bilinçli seçim yapabilir.'),
  ('RSPO sertifikası hangi ürünün sürdürülebilir üretimini hedefler?', 'Palmiye yağı', ['Pamuk ve tekstil lifi', 'Balık', 'Kereste'], 'Sürdürülebilir Palmiye Yağı Yuvarlak Masası, palmiye plantasyonları için ormansızlaşmayı ve biyoçeşitlilik kaybını azaltmayı amaçlayan bir sertifikadır.'),
  ('Bir ülke her yıl kaybolan orman alanını ve türü izleyen bir "kırmızı liste" hazırlıyor. Liste olmadan yapılan koruma çalışmaları neden zayıf kalır?', 'Hangi türlerin ve alanların öncelikli olduğu bilinemez', ['Türler listeye girince büyür', 'Listeler yalnızca turistleri bilgilendirmek için gereklidir ve öncelik belirlemez', 'Listeler yasal olarak yasaktır'], 'Listeler, tehdit düzeyini ve önceliği ortaya koyarak sınırlı kaynakların doğru kullanılmasını sağlar.'),
  ('Binyıl Ekosistem Değerlendirmesi\'ne göre bitkilerin tozlaşmasının sağlanması hangi ekosistem hizmeti grubundadır?', 'Düzenleyici', ['Tedarik', 'Kültürel', 'Destekleyici'], 'Tozlaşma, doğal süreçleri düzenleyen hizmetler arasında sayılır. Besin ve içme suyu tedarik, rekreasyon kültürel, besin döngüsü ise destekleyici hizmetlerdir.'),
  ('Bir ormanın yerel halka odun, yaban meyvesi ve içme suyu sağlaması hangi tür ekosistem hizmetine örnektir?', 'Tedarik hizmeti', ['Düzenleyici hizmet', 'Kültürel hizmet', 'Destekleyici hizmet'], 'Tedarik hizmetleri, ekosistemlerden doğrudan elde edilen madde ve ürünlerdir. Odun, yiyecek ve temiz su bunların başlıca örnekleridir.'),
  ('Toprak oluşumu ve besin elementlerinin döngüsü, ekosistem hizmetleri sınıflandırmasında hangi gruba girer?', 'Destekleyici hizmet', ['Tedarik hizmeti', 'Kültürel hizmet', 'Düzenleyici hizmet'], 'Destekleyici hizmetler diğer üç hizmetin sürmesi için gereklidir. Etkileri insanlara dolaylı ve uzun vadede ulaşır.'),
  ('Henüz tanınmamış bir bitkinin gelecekte ilaç kaynağı olabileceği düşüncesiyle korunmasını savunmak, hangi değer türüne dayanır?', 'Seçenek değeri', ['Varoluş (var olma) değeri', 'Estetik değer', 'Miras değeri'], 'Seçenek değeri, bir kaynağın bugün kullanılmasa bile ileride yararlı çıkabilme olasılığına verilen değerdir. Türler yok olunca bu olasılık da kaybolur.'),
  ('Türlerin ve ekosistemlerin insana yararı olmasa bile kendi başlarına değer taşıdığını savunan görüşe ne ad verilir?', 'İçsel değer', ['Araçsal değer', 'Seçenek değeri', 'Parasal değer'], 'İçsel değer, bir varlığın başkasının amacına hizmet etmesinden bağımsız biçimde kendine ait bir değerinin olduğunu savunur.'),
  ('19. yüzyılda Kuzey Amerika bizonunun milyonlardan binlere düşmesinin ana nedenlerinden biri hangisidir?', 'Deri ve et için ticari avcılık ile demiryolu ağının yayılması', ['Büyük otlakların çölleşmesi', 'Bizonların toplu göçü', 'Bizonlara özgü hastalık'], 'Demiryolları avcıları ve kürk piyasasını bizonlara ulaştırdı; yoğun ticari avcılık birkaç on yıl içinde sürüleri çökertti.'),
  ('Aşağıdaki IUCN kategorilerinden hangisi "tehdit altında" gruba dahil sayılmaz?', 'Yakın tehdit altında (NT)', ['Hassas (VU) kategorisindeki türler', 'Tehlikede (EN)', 'Kritik tehlikede (CR)'], 'Tehdit altında kabul edilen üç kategori VU, EN ve CR\'dir. NT bu eşiğe yaklaşan türler için ayrılmıştır.'),
  ('Madagaskar\'da yerli halkın kullandığı "tavy" olarak bilinen kes-yak tarımı, adanın hangi sorununu hızlandıran etkenlerden biridir?', 'Ormansızlaşma', ['Aşırı yağış', 'Buzul erimesi', 'Okyanus asitlenmesi'], 'Tavy, ormanın yakılıp tarlaya çevrilmesidir. Adaya özgü lemurlar ve diğer endemik türler bu orman kaybından ağır biçimde etkilenir.'),
  ('Amazon ormanlarının kaybında en büyük paya sahip olan arazi kullanımı hangisidir?', 'Sığır otlatma', ['Kentleşme ve konut yapımı', 'Madencilik', 'Balıkçılık'], 'Amazon\'da açılan alanın büyük çoğunluğu önce otlak, ardından soya gibi ürünler için kullanılır. Sığır yetiştiriciliği ormansızlaşmanın başlıca itici gücü olarak kabul edilir.'),
  ('Asya ve Afrika\'da pullarıyla ve eti için yoğun kaçakçılığa konu olan pangolinler hangi bakımdan koruma çalışmalarının odağındadır?', 'Dünyada en çok kaçak ticareti yapılan memeliler arasında olmaları', ['Dünyada en çok sayıda hayvanat bahçesinde ve sirklerde bulunmaları', 'En hızlı ürüyen memeliler olmaları', 'Hiç doğal düşmanı olmayan memeliler olmaları'], 'Pangolin pulları geleneksel ilaç, etleri ise yiyecek olarak talep görür. Tüm pangolin türleri CITES kapsamında uluslararası ticarete kapatılmıştır.'),
  ('Gergedanların boynuzunun güvenli bir yöntemle kesilmesi (dehorning) uygulaması hangi amaçla yapılır?', 'Kaçak avcılar için hedefi caydırmak', ['Hayvanı hasta olmaktan korumak', 'Boynuzların satışından gelir elde etmek', 'Gergedanın yön bulmasını sağlamak'], 'Boynuz keratinden oluşur ve kesildikten sonra yeniden uzar. Boynuzsuz hayvan kaçak avcı için daha az çekici olur.'),
  ('CITES kapsamında tüm kaktüs türleri hangi ek listede yer alır?', 'Ek II', ['Ek I', 'Ek III', 'Hiçbir listede yer almaz'], 'Kaktüs familyasının tamamı CITES Ek II\'dedir; bazı türler ise Ek I\'e alınmıştır. Böylece ticaret izne bağlanır.'),
  ('Akarsu üzerine yapılan barajın yanına balık geçidi (balık merdiveni) yapılmasının amacı nedir?', 'Göçmen balıkların baraj üstüne ve altına geçişini sağlamak', ['Baraj suyunu süzerek temizleyip kalitesini artırmak', 'Suyun akış hızını artırmak', 'Balıkların avlanmasını kolaylaştırmak'], 'Barajlar göçmen balıkların üreme alanlarına ulaşmasını engeller. Balık geçitleri bu bağlantıyı kısmen yeniden sağlar.'),
  ('Kırklareli\'ndeki İğneada Longoz Ormanları Millî Parkı\'nı özgün kılan ekosistem nedir?', 'Taşkın sularıyla beslenen subasar longoz ormanları', ['Yüksek dağ buzulları', 'Kızılçam makilikleri', 'Volkanik krater gölleri'], 'Longoz, nehir ve göl çevresinde yılın belirli döneminde sular altında kalan ormandır. İğneada\'daki longozlar Avrupa\'da az kalan örneklerdendir.'),
  ('Edirne\'deki Gala Gölü Millî Parkı özellikle hangi canlı grubu için önem taşır?', 'Kışlayan su kuşları', ['Yüksek dağ memelileri', 'Mağara yarasaları', 'Çöl sürüngenleri'], 'Gala Gölü, Meriç Deltası çevresinde yer alır ve kışlayan su kuşları için önemli bir sığınaktır.'),
  ('Troya Tarihî Millî Parkı hangi ilimizdedir?', 'Çanakkale', ['Balıkesir', 'İzmir', 'Edirne'], 'Troya antik kenti Çanakkale\'nin Tevfikiye köyü yakınlarındadır. Alan 1998\'de UNESCO Dünya Mirası Listesi\'ne alınmıştır.'),
  ('Hindistan\'da Batı Gatlar\'da bazı ormanlık parçaların yüzyıllardır inanç gerekçesiyle kesilmeden bırakılması koruma biyolojisinde hangi kavramla anılır?', 'Kutsal koru', ['Kale koruma', 'Ekolojik tuzak', 'Tampon bölge'], 'Kutsal korular, yerel inançlar nedeniyle dokunulmadan kalan ormanlardır. Çevresindeki alanlar tarıma açılırken bu parçalar türler için sığınak olmuştur.'),
  ('Kuşaklar boyunca biriken yerel halkın doğa bilgisine, örneğin balık göç zamanlarını ya da otlak döngülerini kapsayan bilgiye ne ad verilir?', 'Geleneksel ekolojik bilgi', ['Yapay seçilim', 'Biyokorsanlık', 'Taksonomik bilgi'], 'Geleneksel ekolojik bilgi, bilimsel verinin yetersiz olduğu yerlerde izleme ve yönetim kararlarına değerli katkı sağlar.'),
  ('Bir ada ekosisteminde yuva yapan kuşları yok eden istilacı sıçanları temizlemek için tek seferde zehirli yem atılması gibi uygulamalar hangi stratejinin parçasıdır?', 'Ada istilacı tür temizliği', ['Yer dışı koruma ve esaret üretimi', 'Biyokorsanlık', 'Kale koruma'], 'Ada ekosistemleri küçük ve yalıtılmış olduğu için istilacı yırtıcıların tamamen temizlenmesi mümkün olabilir. Başarı örnekleri deniz kuşlarının yeniden üremesini sağlamıştır.'),
  ('Yeni Zelanda\'da Zealandia gibi koruma alanlarının çevresinin yırtıcı geçirmez çitle çevrilmesi hangi amaçla yapılır?', 'Yerli kuşları istilacı memeli yırtıcılardan korumak', ['Yerli kuşların uçup ülkeden ayrılmasını önlemek ve engellemek', 'Ziyaretçi sayısını artırmak', 'Deniz suyunu içeri sokmamak'], 'Yeni Zelanda\'nın yerli kuşları memeli yırtıcılara karşı evrimleşmediğinden kolay avlanır. Çit, istilacı yırtıcıları uzak tutarak bu kuşlara sığınak sağlar.'),
  ('Yaşayan Gezegen Endeksi (Living Planet Index) neyi ölçer?', 'İzlenen omurgalı popülasyonlarının zaman içindeki ortalama değişimini', ['Dünyadaki toplam tür sayısını', 'Ormanların karbon miktarını', 'Hayvanat bahçelerinin ziyaretçi sayısını'], 'Endeks, binlerce omurgalı popülasyonunun bolluk verisini birleştirerek biyoçeşitlilik eğilimini gösterir.'),
  ('Hindistan\'ın 1936\'da kurulan, ülkenin ilk millî parkı olan alan hangisidir?', 'Jim Corbett Millî Parkı', ['Kaziranga Millî Parkı', 'Gir Millî Parkı', 'Ranthambore Kaplan Rezervi ve Millî Parkı'], 'Başlangıçta Hailey Millî Parkı adıyla kurulan alan, sonradan avcıdan koruyucuya dönüşen Jim Corbett\'in adını almıştır. Diğer parklar daha sonra kurulmuştur.'),
  ('Alaska\'daki Katmai Millî Parkı, hangi doğa olayını izleyen turistlerle ünlüdür?', 'Kahverengi ayıların şelalede somon avlaması', ['Kutup ışıklarının gökyüzünde sürüklenip renk değiştirmesi', 'Kutup tilkilerinin yüzmesi', 'Balinaların karaya vurması'], 'Brooks Şelalesi\'nde somonlar nehir yukarı göçerken kahverengi ayılar şelale kenarında balık yakalar. Bu, besin zincirinin canlı bir örneğidir.'),
  ('UNESCO\'nun "Tehlike Altındaki Dünya Mirası Listesi" ne amaçla hazırlanır?', 'Ciddi tehdit altındaki alanlara uluslararası dikkat ve destek çekmek', ['Alanları turizme kapatmak', 'Yeni alanları miras listesine eklemek', 'Alanların fiyatını belirlemek'], 'Liste, savaş, kaçak avlanma ya da kirlilik gibi tehditler altındaki alanlar için acil koruma önlemlerini harekete geçirmeyi hedefler.'),
  ('Gerald Durrell\'in 1959\'da Jersey\'de kurduğu hayvanat bahçesinin temel hedefi nedir?', 'Tükenme tehlikesindeki türleri üretip kurtarmak', ['Bütün hayvan türlerini ziyaretçilere sergilemek ve eğlendirmek', 'Hayvanları eğlence için eğitmek', 'Hayvan ticareti yapmak'], 'Jersey Hayvanat Bahçesi, ünlü bir tür koruma merkezidir. Mauritius pembe güvercini gibi bazı türlerin kurtarılmasında rol almıştır.'),
  ('Orman kaybını uydu görüntüleriyle neredeyse gerçek zamanlı izleyen "Global Forest Watch" benzeri araçlar hangi alanda işe yarar?', 'Yasa dışı ormansızlaşmayı hızla fark edip müdahale etmekte', ['Hayvanların yaşını hesaplamakta', 'Tohum satışını artırmakta', 'Orman yangınlarını çıkarmakta'], 'Uydu verileri orman örtüsü kaybını saptar. Böylece yetkililer kaçak kesim ve açma etkinliklerine hızla müdahale edebilir.'),
  ('Ormandaki yarasa ve kuş türlerini görmeden saptamaya yarayan, ses kaydı ve analizine dayalı izleme yöntemine ne denir?', 'Akustik izleme', ['Radyokarbon tarihleme', 'Gen haritalama', 'Kromatografi'], 'Otomatik ses kaydediciler belirli aralıklarla ses toplar; yazılımlar bunlardan türlere özgü çağrıları tanır. Yöntem gizli ve gece aktif türler için özellikle uygundur.'),
  ('Gece yırtıcı hayvanların alanda bulunup bulunmadığını saptamak için ısıl (termal) kameraların kullanılması hangi yararı sağlar?', 'Karanlıkta hayvanların vücut sıcaklığı üzerinden tespitini', ['Hayvanların renklerini ve tüy desenlerini gündüz gibi görmeyi', 'Kuşların göç yönünü değiştirmeyi', 'Yüksek sesli çağrıları kaydetmeyi'], 'Termal görüntüleme, ortam ile hayvan arasındaki sıcaklık farkını algılar. Böylece gece ve yoğun bitki örtüsünde de sayım yapılabilir.'),
  ('Kuzey yarım kürede çok sayıda yapay aydınlatmanın kıyı bölgelerinde yavru yönelimini bozduğu bilinen hayvanlar arasında hangisi vardır?', 'Deniz kaplumbağası yavruları', ['Dağ keçileri ve yaban koyunları', 'Kar leoparları', 'Kutup tilkileri'], 'Yeni çıkan kaplumbağa yavruları denizi ışıktan bulur; yapay ışıklar onları yanlış yöne sürükler. Kıyılarda ışık kısıtlaması bu nedenle uygulanır.'),
  ('Tür çeşitliliğinin ekvatora doğru genel olarak artması (enlemsel gradyan) için öne sürülen açıklamalardan biri hangisidir?', 'Daha fazla güneş enerjisi ve daha uzun süreli kararlı iklim', ['Kutuplarda daha fazla yağış olması', 'Ekvatorda daha az bitki bulunması', 'Kutuplarda daha uzun gün olması'], 'Tropiklerde yıllık enerji girdisi yüksek ve iklim görece kararlıdır; bu da türleşmeyi artırır ve yok oluşu azaltır. Kesin açıklama hâlâ tartışılan bir konudur.'),
  ('Eski bir soydan kalan ve eskiden geniş yayılışlı olup bugün dar alana sıkışmış türlere ne ad verilir?', 'Paleoendemik', ['Neoendemik', 'Kozmopolit', 'İstilacı'], 'Paleoendemikler yaşı çok eski, geçmişte daha geniş dağılmış gruplardır. Neoendemikler ise yakın dönemde oluşup henüz yayılmamış türlerdir.'),
  ('Bir türün bilinen yayılış noktalarını iklim ve habitat değişkenleriyle ilişkilendirerek uygun alanı haritalayan yönteme ne ad verilir?', 'Tür dağılım modellemesi', ['DNA barkodlama ile tür tanıma', 'Yer dışı koruma', 'Kenar analizi'], 'Tür dağılım modelleri, gözlem noktaları ile çevre değişkenleri arasında ilişki kurup hem bugünkü hem gelecekteki uygun alanı tahmin eder. Koruma planlamasında yaygın kullanılır.'),
  ('Bir ormanın içinde bazı ağaçların yüzlerce yıl yaşlanmasına izin verilen "yaşlı orman" alanlarının biyoçeşitlilik açısından önemi nedir?', 'Ölü odun ve boşluklar ile özel türlere yaşam alanı sunması', ['Yaşlı ağaçların hızla büyümesi', 'Yaşlı ormanda hiç canlı bulunmaması', 'Ormanda tür sayısının sıfırlanması'], 'Yaşlı ormanlarda ölü ağaçlar, kovuklar ve çok katlı yapı bulunur. Birçok mantar, böcek ve kuş bu yapılara bağımlıdır.'),
  ('Triyas sonunda gerçekleşen kitlesel yok oluşun ardından hangi grup karasal ekosistemlerde baskın hâle gelmiştir?', 'Dinozorlar', ['Memeliler ve kuşlar', 'Böcekler', 'Amfibiler'], 'Triyas sonu yok oluşu, dinozorların rakiplerini ortadan kaldırarak Jura döneminde baskın hâle gelmelerine olanak verdi.'),
  ('Dinozorların yok oluşuyla ilişkilendirilen çarpma kraterinin bulunduğu yer neresidir?', 'Yucatán Yarımadası', ['Sibirya\'daki geniş lav platoları ve volkanik alan', 'Kuzey Avustralya', 'Türkiye\'nin Anadolu platosu'], 'Chicxulub Krateri, Yucatán Yarımadası\'nın kuzeyinde, kısmen denizin altındadır. Yaşı yaklaşık 66 milyon yıldır.'),
  ('Çiftçilerin kurt saldırısında kaybettikleri hayvanlar için devletten tazminat alması, koruma açısından neden savunulur?', 'Misilleme amaçlı öldürmeyi azaltabilir', ['Kurt sayısını doğrudan ve hızla artırıp ormana yayar', 'Çiftçiyi hayvancılıktan uzaklaştırır', 'Kurtların evcilleşmesini sağlar'], 'Tazminat, hayvan sahibinin kaybını telafi ederek yırtıcıya karşı hoşgörüyü artırır. Ancak ödeme doğrulama süreçlerinin hızlı ve adil olması gerekir.'),
  ('Yaban domuzu ve ayıların tarım alanlarına girip zarar vermesini önlemenin yaygın ve yaşama zarar vermeyen bir yolu nedir?', 'Elektrikli çit', ['Hayvanlara zehirli yem koymak', 'Ormanı kesmek', 'Hayvanları besleyerek alıştırmak'], 'Elektrikli çitler hayvanı fiziksel zarar vermeden caydırır. İnsan-yaban hayatı çatışmasını azaltmada ucuz ve etkili yöntemlerdendir.'),
  ('Millî parktaki ziyaretçilerin ayılara veya maymunlara yiyecek vermesinin tehlikeli olmasının ana nedeni nedir?', 'Hayvanlar insana alışıp zararlı hâle gelir ve çoğu zaman öldürülür', ['Hayvanlar çok şişmanlar', 'Yiyecek hayvanları kaçırır', 'Hayvanların sesleri artar'], 'Beslenmeye alışan hayvanlar insanlardan korkmaz, yemek aramak için yerleşim yerlerine gelir. Bu da hayvan için ölümcül sonuçlar doğurur.'),
  ('Yangın riski yüksek bir ormanda, yakıt yükünü azaltmak için küçük alanlarda önceden planlanıp denetlenen yakmalar yapılması hangi uygulamadır?', 'Kontrollü yakma', ['Orman düzenleme', 'Biyolojik mücadele', 'Yeniden yerleştirme'], 'Kontrollü yakma, kuru ot ve çalı birikimini azaltarak büyük yangın riskini düşürür ve bazı türlerin yenilenmesine yardım eder. Bu yöntem iklim ve uzmanlık gerektirir.'),
  ('Serbest dolaşan evcil kedilerin yerel kuş ve küçük hayvan popülasyonlarına verdiği zararı azaltmak için sahiplere hangi öneri yapılır?', 'Kedileri özellikle üreme mevsiminde içeride tutmak', ['Kedilere daha çok yem vererek dışarıda tutmaya devam etmek', 'Kedileri doğaya salmak', 'Kedilerin tırnaklarını boyamak'], 'Evde tutulan kediler yaban hayvanlarını avlayamaz. Kısırlaştırma ve izlemeyle de dolaşan kedilerin sayısı azaltılabilir.'),
  ('Tohum bankası için örnek toplarken çok sayıda farklı ana bitkiden tohum alınmasının amacı nedir?', 'Popülasyonun genetik çeşitliliğini temsil etmek', ['Toplama süresini kısaltıp bütün tohumların aynı bitkiden alınmasını sağlamak', 'Tohumların daha hızlı çimlenmesini sağlamak', 'Maliyeti düşürmek'], 'Tek ya da birkaç bitkiden alınan tohum, popülasyondaki çeşitliliğin küçük bir bölümünü taşır. Çok sayıda anne bitkiden toplama alel zenginliğini korur.'),
  ('Koruma yönetiminde, sonuçları izleyip sonuçlara göre yöntemi sürekli güncelleyen yaklaşıma ne ad verilir?', 'Uyarlanabilir yönetim', ['Katı ve değişmez yönetim', 'Tek seferlik yönetim', 'Rastgele yönetim'], 'Uyarlanabilir yönetim, belirsizlik altında "dene, izle, öğren, ayarla" döngüsü izler. Böylece başarısız uygulamalar erken fark edilir.'),
  ('Yerel halkın yaban hayatı gözlem rehberliği yapmasını sağlayan eğitim programları koruma açısından hangi sonucu doğurur?', 'Alternatif gelir sağlayarak avcılığa bağımlılığı azaltır', ['Yerel halkı bölgeden uzaklaştırır', 'Kaçak avcılığı mutlaka artırır', 'Ziyaretçi sayısını sıfıra indirir'], 'Eğitimli rehberler turizmden gelir elde ettiğinde, hayvanları korumanın ekonomik yararı görünür hâle gelir.'),
  ('Tarla sınırlarındaki çit bitkilerinin (çalı ve ağaç sıraları) korunmasının biyoçeşitliliğe katkısı nedir?', 'Küçük hayvanlara barınak ve hareket koridoru sağlaması', ['Tarlayı daha çok güneşe ve rüzgâra maruz bırakarak toprağı kurutması', 'Yabani hayvanları uzaklaştırması', 'Toprağı sertleştirmesi'], 'Çit bitkileri kuşlara, böceklere ve küçük memelilere yuva ve besin sağlar; ayrıca tarım alanları arasında bağlantı kurar.'),
  ('Tarlaların kenarına ekilen çiçekli şeritlerin amacı nedir?', 'Tozlaştırıcı ve yararlı böceklere besin ve yaşam alanı sağlamak', ['Zararlıların sayısını artırmak', 'Toprağı sıkıştırmak', 'Mahsulün rengini değiştirmek'], 'Çiçekli şeritler nektar ve polen kaynağıdır. Tozlaştırıcıları ve zararlıların doğal düşmanlarını çiftliğe çeker.'),
  ('1959 tarihli Antarktika Antlaşması\'nın temel ilkelerinden biri nedir?', 'Kıtanın yalnızca barışçıl ve bilimsel amaçlarla kullanılması', ['Kıtanın ülkeler arasında bölüşülmesi', 'Kıtada askerî üs kurulması', 'Kıtada sanayi tesisi kurulması'], 'Antlaşma, Antarktika\'nın askerî amaçla kullanılmasını yasaklar ve bilimsel işbirliğini öne çıkarır. Madrid Protokolü sonradan çevre korumayı güçlendirmiştir.'),
  ('Spix makavı 2000\'de doğada tükendi. 2022\'de Brezilya\'da hangi gelişme yaşandı?', 'Esaret altında üretilen bireylerin doğaya salınması', ['Yeni bir vahşi popülasyon keşfedildi', 'Türün hem doğada hem esarette tamamen tükendiği resmen onaylandı', 'Tür hayvanat bahçelerinden çıkarıldı'], 'Esarette üretilen Spix makavı bireyleri Brezilya\'nın Caatinga bölgesine salındı. Bu, türü doğaya geri kazandırma çabası olarak görüldü.'),
  ('Brezilya\'nın doğusundaki Atlantik Ormanı, hangi nedenle dünyanın önde gelen biyoçeşitlilik sıcak noktalarındandır?', 'Çok sayıda endemik tür barındırması ve ormanının büyük kısmının yok olmuş olması', ['Hiç insan yaşamaması', 'Hiç endemik tür barındırmaması', 'Tamamen çöl olması'], 'Sıcak nokta ölçütü, yüksek endemizm ve yoğun habitat kaybının birleşimidir. Atlantik Ormanı bu iki ölçütü de karşılar.'),
  ('Haudenosaunee (İrokua) topluluklarının karar alırken yedi kuşak sonrasını düşünmesi ilkesi, koruma anlayışında neyi vurgular?', 'Kararların uzak gelecekteki kuşaklara etkisini', ['Kararların yalnızca bugünkü kuşağın çıkarına göre alınmasını', 'Doğanın tamamen yok olmasını', 'Karar alma sürecinin hiç yapılmamasını'], 'Yedinci kuşak ilkesi, bugünkü kararların gelecekteki nesillerin refahına etkisini gözetmeyi öğütler. Sürdürülebilirlik düşüncesiyle örtüşür.'),
  ('Bir koruma biyoloğu 500 tohumun çimlenme testinde %80 çimlenme oranı buluyor. Bu bankadaki 20 000 tohumun yaklaşık kaçının çimlenmesi beklenir?', '16 000', ['4 000', '800 000', '18 000'], 'Çimlenme oranı %80 ise 20 000 × 0,8 = 16 000 tohum çimlenir. Düşük çimlenmeli türlerde yaşayabilir tohum miktarını artırmak gerekir.'),
  ('Bir istilacı türle mücadelede "eradikasyon" ile "kontrol" arasındaki fark nedir?', 'Eradikasyon türü bölgeden tamamen yok etmeyi, kontrol ise sayısını zararsız düzeyde tutmayı hedefler', ['Eradikasyon yalnızca bitkilere uygulanır', 'Kontrol türü tamamen ortadan kaldırır', 'İkisi aynı yöntemdir'], 'Eradikasyon küçük ve yalıtılmış alanlarda mümkün olabilir. Yaygınlaşmış türlerde ise genellikle kontrol, yani zararı azaltacak sayı baskısı uygulanır.'),
  ('Bir yerde ilk görülen yabancı bir türe hemen ve küçük çaplı müdahale edilmesinin, yayıldıktan sonra mücadeleye kıyasla avantajı nedir?', 'Daha az maliyetle ve daha yüksek başarı şansıyla çözülebilmesi', ['Türün daha hızlı yayılması', 'Türün yerli sayılması', 'Yerli türlerin tükenmesi'], 'Yayılma başlamadan yapılan müdahale hem ucuzdur hem eradikasyon ihtimali yüksektir. Gecikilirse maliyet ve belirsizlik artar.'),
  ('Sulak alanlarda avcıların kullandığı kurşun saçmaların dipte kalıp su kuşları tarafından yutulması hangi sorun yaratır?', 'Kurşun zehirlenmesi ve ölüm', ['Kuşların daha hızlı büyümesi', 'Su kalitesinin artması', 'Kuşların göçünün hızlanması'], 'Su kuşları sindirimlerine yardımcı olmak için küçük taşları yutar. Kurşun saçmayı da yutunca zehirlenirler; bu nedenle birçok ülkede sulak alanlarda kurşun saçma yasaklanmıştır.'),
  ('Asit yağmurlarının göllerin pH değerini düşürmesi, göl ekosisteminde hangi sonucu doğurabilir?', 'Balık ve diğer duyarlı türlerin azalması', ['Tür çeşitliliğinin ve balık sayısının artması', 'Suyun daha berrak ve bazik olması', 'Su kuşlarının çoğalması'], 'Asitlenen sularda alüminyum çözünür, yumurta ve yavru gelişimi zarar görür. Duyarlı türler yok olurken göl berraklaşabilir ama cansızlaşır.'),
  ('Yaban hayatı ticaretini izleyen ve WWF ile IUCN\'nin ortak programı olarak çalışan ağ hangisidir?', 'TRAFFIC', ['IPBES', 'Ramsar Sekreteryası', 'Global Forest Watch'], 'TRAFFIC, yaban hayvanı ve bitki ticaretini izleyerek kaçakçılık yollarını belirlemeye ve politika önerisi sunmaya çalışır.'),
  ('Bir restorasyon projesinde fidan ve tohumların aynı bölgeden toplanarak kullanılması hangi ilkeye dayanır?', 'Yerel köken ilkesi', ['Yabancı tür kullanma ilkesi', 'Tek klon ilkesi', 'Ucuz fidan ilkesi'], 'Yerel kökenli bitki materyali, o bölgenin iklimine ve toprağına uyum sağlamış genleri taşır. Uzak bölgeden getirilen bitkiler uyumsuz olabilir.'),
  ('WWF\'nin "Global 200" listesinde yer alan alanlar ne anlama gelir?', 'Dünyanın biyolojik açıdan en seçkin 200 ekobölgesi', ['Yaşı 200 yılı aşan ağaçların korunduğu ormanlar', '200 milyon yıllık fosiller', '200 türlük hayvanat bahçeleri'], 'Global 200, farklı biyomlardaki en olağanüstü ve temsilî ekobölgeleri öncelikli koruma hedefi olarak belirler.'),
  ('Sıfır Yok Oluş İttifakı (AZE) alanları nasıl tanımlanır?', 'Tehlike altındaki bir türün tüm popülasyonunun tek bir alanda yaşadığı yerler', ['Hiçbir türün yaşamadığı çöller', 'Yalnızca tarım alanları', 'Yalnızca şehir parkları'], 'AZE alanlarında kritik tehlikedeki ya da tehlikedeki türün neredeyse tüm bireyi tek yerde bulunur. Bu alan kaybolursa tür de tükenir.'),
  ('Ekosistem hizmetleri için ödeme (PES) programı hangi mantıkla çalışır?', 'Hizmeti sağlayan arazi sahiplerine, hizmetten yararlananların ödeme yapması', ['Hizmeti kullananlara ceza kesilmesi', 'Arazi sahiplerinin vergi ödemesi', 'Doğanın tamamen kamulaştırılması'], 'PES\'te örneğin su kullanıcıları, yukarı havzadaki ormanı koruyan topluluklara ödeme yapar. Böylece koruma ekonomik bir kazanca dönüşür.'),
  ('Bir köyün bölgedeki hayvanları kendisinin izleyip kaydettiği "topluluk temelli izleme" yaklaşımının sağladığı bir yarar nedir?', 'Düşük maliyetle sürekli veri toplayıp sahiplenmeyi artırmak', ['Bilimsel yöntemleri tamamen dışlamak', 'Yalnızca uzmanların kayıt tutması', 'Verinin yalnızca bir kez toplanması'], 'Yerel halkın sahada sürekli bulunması izlemeyi ucuzlaştırır ve topluluğun korumada söz sahibi olmasını güçlendirir.'),
  ('Michael Soulé, koruma biyolojisini nasıl tanımlamıştır?', 'Hedefi kriz altındaki biyoçeşitliliği korumak olan görev odaklı bir bilim dalı', ['Yalnızca hayvan davranışı bilimi', 'Yalnızca ormancılık yöntemleri bilimi', 'Ekonomi bilimi'], 'Soulé 1985\'te koruma biyolojisini bir "kriz disiplini" olarak tanımladı; bilgi eksik olsa da hızlı karar vermeyi gerektirir.'),
  ('Genetik, tür ve ekosistem çeşitliliği olmak üzere üç düzeyli biyoçeşitlilik tanımında, aynı buğday türünün farklı yerel çeşitlerinin bulunması hangi düzeye girer?', 'Genetik çeşitlilik', ['Tür çeşitliliği', 'Ekosistem çeşitliliği', 'Habitat çeşitliliği'], 'Aynı türün farklı çeşit ya da popülasyonları arasındaki alel farklılıkları genetik çeşitliliği oluşturur. Tür çeşitliliği ise farklı türlerin sayısıdır.'),
  ('Bir bölgede orman, sulak alan, bozkır ve kıyı kumulu gibi farklı yaşam topluluklarının bulunması hangi çeşitlilik düzeyini ifade eder?', 'Ekosistem çeşitliliği', ['Genetik çeşitlilik', 'Tür çeşitliliği', 'Alel çeşitliliği'], 'Ekosistem çeşitliliği, bir alandaki farklı yaşam ortamlarının ve topluluk tiplerinin çeşitliliğidir.'),
  ('Maden sahalarında kazı sırasında üst toprağın ayrı yığınlarda saklanıp sonradan serilmesinin amacı nedir?', 'Tohum bankası ve verimli toprak katmanını korumak', ['Kazı maliyetini artırmak', 'Toprağı satmak', 'Madeni zenginleştirmek'], 'Üst toprakta organik madde, mikroorganizma ve tohum bulunur. Bu tabaka korunursa bitki örtüsünün yeniden oluşması hızlanır.'),
  ('Çıplak ve verimsiz bir alanda ilk yerleşen, toprağı hazırlayan ve zamanla başka türlere zemin hazırlayan türlere ne ad verilir?', 'Öncü türler', ['Şemsiye türler', 'Gösterge türler', 'İstilacı türler'], 'Öncü türler zor koşullara dayanıklıdır; toprağı zenginleştirir ve gölge sağlar. Bu yüzden restorasyonda başlangıç bitkileri olarak kullanılır.'),
  ('Türkiye Anayasası\'nın 56. maddesi hangi hakkı güvence altına alır?', 'Herkesin sağlıklı ve dengeli bir çevrede yaşama hakkını', ['Herkesin ücretsiz konut hakkını', 'Herkesin av yapma hakkını', 'Herkesin ormanı kullanma hakkını'], 'Madde 56, sağlıklı ve dengeli bir çevrede yaşamayı herkesin hakkı sayar; çevreyi geliştirmeyi ve kirliliği önlemeyi devlete ve vatandaşlara görev olarak verir.'),
  ('Hayvan refahında "Beş Özgürlük" ilkesinden biri aşağıdakilerden hangisidir?', 'Açlık ve susuzluktan uzak olma', ['Üreme hakkından yoksun olma', 'Sürekli aynı kafeste yaşama', 'Başka türlerle hiç karşılaşmama'], 'Beş Özgürlük açlık-susuzluktan, rahatsızlıktan, acı-yaralanma-hastalıktan, korku-sıkıntıdan ve doğal davranışı sergileyebilme özgürlüklerini içerir.'),
  ('Nadir bir kuş türünün yuvalama yerlerini artırmak için kuruldukları ağaçlara ya da kayalıklara yerleştirilen yapay kutulara ne ad verilir?', 'Yuva kutuları', ['Gözetleme kuleleri', 'Elektrik direkleri', 'Gıda istasyonları'], 'Doğal kovuk sayısının azaldığı alanlarda yuva kutuları kovukta yuva yapan kuşlara üreme olanağı sağlar.'),
  ('Asya çitasının günümüzde doğal ortamında hayatta kalan son popülasyonu hangi ülkede bulunur?', 'İran', ['Hindistan', 'Irak', 'Suudi Arabistan'], 'Asya çitası bir zamanlar Orta Doğu\'dan Hindistan\'a kadar yayılıyordu, bugün yalnızca İran\'ın çöl bölgelerinde çok az sayıda kalmıştır.'),
  ('IUCN\'nin "Tür Hayatta Kalma Komisyonu" (SSC) ne tür bir yapıdır?', 'Tür ve türlerle ilgili uzman gruplarından oluşan gönüllü bilim ağı', ['Hayvanat bahçesi şirketi', 'Yalnızca hükûmet kurumu', 'Turizm acentesi'], 'SSC, binlerce uzmanı tür grupları halinde birleştirir ve Kırmızı Liste değerlendirmelerine katkı verir.'),
  ('Sakarya Meydan Muharebesi Tarihî Millî Parkı hangi ilimizin sınırları içindedir?', 'Ankara', ['Eskişehir', 'Sakarya', 'Kütahya'], 'Millî Mücadele\'nin önemli muharebelerinden Sakarya Meydan Muharebesi Ankara\'nın Polatlı ilçesi çevresinde yapılmıştır; tarihî millî park bu alanı korur.'),
  ('Dünya Günü (Earth Day) ilk kez hangi yılda ve hangi tarihte kutlanmıştır?', '1970, 22 Nisan', ['1992, 5 Haziran', '1972, 3 Mart', '1987, 22 Mayıs'], 'İlk Dünya Günü 22 Nisan 1970\'te ABD\'de çevre bilincini artırmak için düzenlenmiş; bugün dünyanın birçok ülkesinde kutlanmaktadır.'),
  ('1987\'de Brundtland Komisyonu\'nun yayımladığı rapor hangi adla bilinir?', 'Ortak Geleceğimiz', ['Sessiz Bahar', 'Büyümenin Sınırları', 'Küçük Güzeldir'], '"Ortak Geleceğimiz" raporu, sürdürülebilir kalkınma kavramını küresel gündeme yerleştirmiştir.'),
  ('Bhutan\'ın anayasasında ülke alanının en az yüzde kaçının ormanla kaplı kalması gerektiği hükme bağlanmıştır?', '60', ['30', '40', '90'], 'Bhutan anayasası orman örtüsünün en az %60 olmasını şart koşar. Ülke ormanları korumada çarpıcı bir politika örneği olarak gösterilir.'),
  ('Bir kuş türünde 100 yumurtanın %20\'si kuluçkadan çıkıyor, çıkan yavruların %50\'si ilk yıl hayatta kalıyorsa ilk yılı geçen birey sayısı kaçtır?', '10', ['20', '50', '30'], '100 × 0,20 = 20 yavru; 20 × 0,50 = 10 birey ilk yılı geçer. Her aşamada hayatta kalma oranları çarpılır.'),
  ('Herbaryum örneklerinin koruma çalışmaları için taşıdığı değer nedir?', 'Bir türün geçmişte nerelerde ve ne zaman bulunduğuna dair kayıt sağlaması', ['Bitkilerin yeniden canlanması', 'Türleri doğaya doğrudan salması', 'Türlerin fiyatını belirlemesi'], 'Kurutulup saklanmış örnekler toplama yeri ve tarihini içerir. Bu bilgi, türlerin dağılımının zaman içinde nasıl değiştiğini gösterir.'),
  ('Dağ gorili turizminde ziyaretçilerin en az yedi metre mesafede kalması ve hastaysa gorillere yaklaşmaması kuralının nedeni nedir?', 'İnsan solunum hastalıklarının gorillere bulaşmasını önlemek', ['Gorillerin ziyaretçiden korkup ormandan uzaklaşmasını tümüyle engellemek', 'Gorillerin fotoğraf çekmesini sağlamak', 'Orman yolunun korunmasını sağlamak'], 'Goriller insan hastalıklarına karşı bağışıklığı zayıf olan hayvanlardır. Grip gibi enfeksiyonlar bir grubun tamamını etkileyebilir; bu yüzden mesafe ve sağlık kuralları uygulanır.'),
  ('Avrupa\'da yabani tilkilere kuduz aşısı içeren yemlerin havadan ya da elle serpilmesi, hangi yaklaşımın örneğidir?', 'Yaban hayvanı hastalıklarını popülasyon düzeyinde kontrol eden aşılama programı', ['Tilkilerin tamamen öldürülmesi', 'Tilkilerin hayvanat bahçesine alınması', 'Tilkilerin evcilleştirilmesi'], 'Oral aşı yemleri, tilkilerde kuduz bulaşını keserek hem insan hem hayvan sağlığını korumuştur. Birçok Batı Avrupa ülkesi bu yöntemle kuduzdan arındırılmıştır.'),
  ('Avrupa Birliği\'nin Kuş ve Habitat direktiflerine dayanan, ortak koruma alanları ağı hangi adla bilinir?', 'Natura 2000', ['Emerald', 'Ramsar Ağı', 'Biyosfer Ağı'], 'Natura 2000, AB üyelerinin belirlediği özel koruma alanlarını ve Habitat Direktifi alanlarını kapsar; dünyanın en büyük koordineli koruma ağlarından biridir.'),
  ('Hayvanlarda hastalığın korunan bir popülasyondan başka bir popülasyona aktarılmasını önlemek için nakil (translokasyon) öncesinde yapılan işlem hangisidir?', 'Karantina ve sağlık taraması', ['Tüm hayvanları aşılamadan salmak', 'Hayvanları aç bırakmak', 'Hayvanların yalnızca yaşını ölçmek'], 'Taşınan hayvanların yeni alana hastalık getirmesi ya da yerel hastalıklara yakalanması riskine karşı karantina ve sağlık taraması standart uygulamadır.'),
  ('Bir adadaki 500 bitki türünün 120\'si yalnızca bu adada bulunuyorsa endemizm oranı yüzde kaçtır?', '%24', ['%12 civarı', '%42', '%76'], '120/500 = 0,24. Adanın endemizm oranı %24\'tür; endemizm adalarda ve dağlarda daha yüksektir.'),
  ('IUCN Kırmızı Liste\'de "En Az Endişe" (LC) kategorisine genellikle hangi türler girer?', 'Geniş yayılışlı, yaygın ve belirgin bir tehdit eğilimi taşımayan türler', ['Yalnızca nadir endemik türler', 'Yalnızca tükenmiş türler', 'Yalnızca esaretteki türler'], 'LC, değerlendirilmiş ve tehdit altı ya da yakın tehdit altı kriterlerini karşılamayan türleri kapsar. Bu kategori yaygın türlerin de gözden kaçmaması gerektiğini hatırlatır.'),
  ('Bir tür bir bölgeden tükendikten onlarca yıl sonra komşu bölgelerden bireylerin gelmesiyle kendiliğinden geri dönüyorsa bu olguya ne ad verilir?', 'Doğal yeniden kolonileşme', ['Yeniden yerleştirme', 'Yardımlı göç', 'Geri ırklama'], 'Bireylerin insan yardımı olmadan boş alana yeniden yerleşmesine yeniden kolonileşme denir. Yeniden yerleştirmede ise bireyleri insan taşır.'),
  ('Tehdit altındaki türleri etkileyen tehditler sınıflandırıldığında hangi grup en sık karşılaşılan tehditlerdendir?', 'Tarım ve su ürünleri üretimi', ['Havai fişek gösterileri ve aydınlatma', 'Kıyıda şemsiye kullanımı', 'Uzay çöpü'], 'Tarım ve su ürünleri üretimi, arazi dönüşümü yoluyla çok sayıda tehdit altı tür üzerinde baskı kurar. Aşırı avlanma ve kereste kesimi de önde gelen tehditlerdir.'),
  ('Bir türün adı "kozmopolit" olarak belirtiliyorsa bu ne anlama gelir?', 'Dünyanın hemen her yerinde bulunabilir', ['Yalnızca tek bir adada ve çevresinde yaşar', 'Yalnızca mağarada yaşar', 'Yalnızca tuzlu suda yaşar'], 'Kozmopolit türler çok geniş coğrafyada görülür; endemik türlerin tam karşıtıdır.'),
  ('Botsvana\'daki Chobe Millî Parkı, hangi hayvanın Afrika\'daki en yoğun popülasyonlarından birini barındırmasıyla tanınır?', 'Afrika filinin', ['Dev pandanın', 'Kutup ayısının', 'Kar leoparının ve kutup tilkisinin'], 'Chobe Nehri çevresindeki alan, fil sürülerinin kuru mevsimde kalabalıklaştığı bir bölgedir. Fil yoğunluğu aynı zamanda bitki örtüsüne baskı oluşturduğu için yönetimi tartışılır.'),
  ('İki farklı gözlemcinin aynı alanda farklı sayıda kuş sayması, hangi sorunun örneğidir?', 'Gözlemci yanlılığı', ['Tür-alan ilişkisi', 'Kenar etkisi', 'Yok oluş borcu'], 'Gözlemcilerin deneyim, işitme ve dikkat farkları sayım sonuçlarını değiştirir. Bu yüzden eğitim, standart protokol ve gözlemci etkisinin modele katılması önerilir.'),
  ('Bir koruma planında hedefin "belirli, ölçülebilir, ulaşılabilir, ilgili ve zamana bağlı" olması gerektiğini ifade eden kısaltma nedir?', 'SMART', ['CITES', 'REDD', 'AZE'], 'SMART hedefleri, ilerlemenin izlenebilmesi için açık ölçütler içerir. Koruma standartlarında planın başarısı bu hedeflere göre değerlendirilir.'),
  ('Bir koruma projesine başlamadan önce, projeden etkilenecek ya da onu etkileyecek tüm kişi ve kurumların belirlenip çıkarlarının incelenmesine ne denir?', 'Paydaş analizi', ['Genetik analiz', 'Spektrum analizi', 'Alan taraması'], 'Paydaş analizi, yerel halk, devlet kurumları, işletmeler ve sivil toplumun rolünü belirler. Uzun vadeli başarı için bu grupların desteği gerekir.'),
  ('Kırsal göç sonucu terk edilen tarım arazilerinin insan müdahalesi olmadan doğal yeniyetişmeye bırakılması hangi yaklaşım olarak adlandırılır?', 'Pasif yeniden yabanıllaştırma', ['Yer dışı koruma ve esaret üretimi programı', 'Geri ırklama', 'Yardımlı göç'], 'Pasif yeniden yabanıllaştırmada alan doğal süreçlere bırakılır. Avrupa\'nın bazı kırsal kesimlerinde orman ve büyük memeli popülasyonları bu yolla yeniden yayılmıştır.'),
  ('Terk edilmiş bir taş ocağının dolup göle dönüşmesine ve çevresine yerli bitki dikilmesine izin verilmesi, hangi yaklaşıma örnektir?', 'Madencilik sonrası yaban hayatı odaklı rehabilitasyon', ['Madenin yeniden açılıp üretiminin daha da genişletilmesi ve derinleştirilmesi', 'Alanın yapılaşmaya açılması', 'Alanın zehirli atık deposu yapılması'], 'Maden sonrası alanlar, sığ kıyıları ve çeşitli yaşam alanlarıyla su kuşları ve böcekler için değerli habitatlara dönüştürülebilir.'),
  ('İzmir\'deki Gediz Deltası, Türkiye\'de hangi kuş grubunun Ege\'deki en önemli üreme ve konaklama alanlarından biridir?', 'Flamingo ve diğer sulak alan kuşları', ['Kutup kuşları', 'Çöl kuşları', 'Kar kuşları'], 'Gediz Deltası\'ndaki tuzlalar ve lagünler, flamingo ve birçok su kuşu için üreme ve dinlenme alanıdır. Alan Ramsar listesindedir.'),
  ('Ekolojik dayanıklılık (resilience) kavramı bir ekosistem için ne ifade eder?', 'Bozulmadan sonra işlev ve yapısını geri kazanabilme yeteneğini', ['Hiç değişmeden kalma yeteneğini', 'Yalnızca hızlı büyüme yeteneğini', 'Yalnızca büyük hayvanlara sahip olmayı'], 'Dayanıklı ekosistemler yangın, kuraklık ya da kirlilik gibi sarsıntılardan sonra temel işlevlerini yeniden kurabilir. Direnç ise değişime hiç uğramama eğilimidir.'),
  ('Kentlerde yağmur suyunu tutan parklar, ıslak çayırlar ve yeşil çatılar gibi planlı doğal ve yarı doğal alanlara ne ad verilir?', 'Yeşil altyapı', ['Gri altyapı', 'Kara delik', 'Kenar etkisi'], 'Yeşil altyapı, doğa temelli çözümlerle taşkını azaltır, ısıyı düşürür ve kent içinde biyoçeşitliliğe yaşam alanı sağlar.'),
  ('Türkiye\'de millî parkların, tabiat parklarının, tabiat anıtlarının ve yaban hayatının yönetiminden sorumlu olan genel müdürlük hangisidir?', 'Doğa Koruma ve Millî Parklar Genel Müdürlüğü', ['Devlet Su İşleri ve Baraj Yönetimi Genel Müdürlüğü', 'Karayolları Genel Müdürlüğü', 'Meteoroloji Genel Müdürlüğü'], 'Doğa Koruma ve Millî Parklar Genel Müdürlüğü, korunan alanların ilanı, yönetimi ve yaban hayatı politikalarıyla ilgilenir.'),
  ('Bir türün yok olmasının yalnızca o türü değil, ona bağımlı başka türleri de yok etmesi hangi kavramla anlatılır?', 'Ko-ekstinksiyon', ['Kurucu etkisi ve rastlantısal alel kaybı süreci', 'Genetik sürüklenme', 'Kenar etkisi'], 'Ko-ekstinksiyonda parazit, tozlaştırıcı ya da yırtıcı gibi bağımlı türler, konak ya da av türü kaybolunca onunla birlikte yok olur.'),
  ('IUCN Kırmızı Liste\'de bir türün sayfasında yer alan "popülasyon eğilimi" ifadesi neyi belirtir?', 'Türün sayısının azaldığı, arttığı ya da sabit kaldığını', ['Türün gelecekteki fiyatını', 'Türün yaşam süresini', 'Türün rengini'], 'Kırmızı Liste her tür için popülasyonun azalan, durağan, artan veya bilinmeyen eğilimde olduğunu bildirir. Bu bilgi risk kategorisini destekler.'),
  ('Gece gökyüzünün korunması için ışık kirliliğini sınırlayan alanlara (örneğin "Karanlık Gökyüzü Parkı") verilen statünün koruma açısından yararı nedir?', 'Gece aktif hayvanların rahatsız edilmesini azaltması', ['Hayvanların gündüz saatlerinde uyumasını ve gece uyanmasını sağlaması', 'Bitkilerin fotosentezini engellemesi', 'Göç yollarının kapanması'], 'Yapay ışık gece yaşayan böcek, yarasa ve göçmen kuşların davranışını bozar. Karanlık gökyüzü alanları bu etkiyi azaltır ve gökyüzü gözlemini de olanaklı kılar.'),
];
